{"type": "tool_use", "name": "write_file", "tool_call_id": "u9Mnr40mOb6beHYFaYodgEJcITfJ7arO", "input": {"path": "build_summary.py", "content": "import csv, glob, json

files = sorted(glob.glob("sales_2026-*.csv"))
assert len(files) == 12, f"expected 12 files, got {len(files)}"

months = {}
region_rev = {}
skipped = 0

for f in files:
    key = f.split("_")[1].replace(".csv", "")
    with open(f, newline="") as fh:
        reader = csv.DictReader(fh)
        assert set(reader.fieldnames) == {"region", "sku", "qty", "unit_price"}, (f, reader.fieldnames)
        for row in reader:
            qty = row["qty"].strip()
            if qty == "":
                skipped += 1
                continue
            try:
                qty = float(qty)
            except ValueError:
                skipped += 1
                continue
            revenue = qty * float(row["unit_price"])
            months[key]["rows_used"] = months[key].get("rows_used", 0) + 1
            months[key]["revenue"] = months[key].get("revenue", 0.0) + revenue
            region_rev[row["region"]] = region_rev.get(row["region"], 0.0) + revenue

for k in months:
    months[k]["revenue"] = round(months[k]["revenue"], 2)

# top region across all months using same rows
top = max(region_rev.items(), key=lambda kv: round(kv[1], 2))
top_region = {"region": top[0], "revenue": round(top[1], 2)}

summary = {"months": months, "skipped_rows": skipped, "top_region": top_region}
with open("summary.json", "w") as fh:
    json.dump(summary, fh, indent=2)

print(json.dumps(summary, indent=2))
print("skipped total:", skipped)
print("region_rev:", {r: round(v,2) for r,v in region_rev.items()})
